// configuration allowed strapi categories
const VALID_CATEGORIES = [
  "Market Outlook", 
  "Financial Planning", 
  "Investing Wisdom", 
  "Library Wisdom", 
  "Innovation Odyssey"
];

const DEFAULT_CATEGORY = "Market Outlook"; 

// helper to decode html entities
// FIXED: Removed .trim() from here to preserve spaces around links
function decodeHtmlEntities(text) {
  if (!text) return "";
  const entities = { '&amp;': '&', '&lt;': '<', '&gt;': '>', '&quot;': '"', '&#39;': "'", '&nbsp;': ' ' };
  return text.replace(/&amp;|&lt;|&gt;|&quot;|&#39;|&nbsp;/g, match => entities[match]);
}

// helper to check if text is a url
function isUrl(text) {
  return /^(http:\/\/|https:\/\/|www\.)/i.test(text.trim());
}

// helper to calculate read time
function calculateReadTime(text) {
  const wordsPerMinute = 200;
  const words = text.split(/\s+/).length;
  const minutes = Math.ceil(words / wordsPerMinute);
  return `${minutes} min read`;
}

// helper to normalize category
function normalizeCategory(inputCat) {
  if (!inputCat) return DEFAULT_CATEGORY;

  let clean = inputCat.trim();

  // 1. case insensitive check
  const match = VALID_CATEGORIES.find(
    cat => cat.toLowerCase() === clean.toLowerCase()
  );

  if (match) {
    return match; 
  }

  // 2. fuzzy match
  const lower = clean.toLowerCase();
  if (lower.includes("library")) return "Library Wisdom";
  if (lower.includes("investing")) return "Investing Wisdom";
  if (lower.includes("planning")) return "Financial Planning";
  if (lower.includes("innovation")) return "Innovation Odyssey";

  return DEFAULT_CATEGORY;
}

// helper to parse text and keep <a> links valid
function parseInlineContent(html) {
  const nodes = [];
  // regex to find <a ... href="...">...</a>
  const linkRegex = /<a\s+(?:[^>]*?\s+)?href=["']([^"']+)["'][^>]*>(.*?)<\/a>/gi;

  let lastIndex = 0;
  let match;

  while ((match = linkRegex.exec(html)) !== null) {
    const [fullMatch, url, linkText] = match;
    const index = match.index;

    // add text before the link
    if (index > lastIndex) {
      const textPart = html.substring(lastIndex, index);
      // clean tags but KEEP spaces
      const cleanText = decodeHtmlEntities(textPart.replace(/<[^>]+>/g, '')); 
      if (cleanText) {
        nodes.push({ type: "text", text: cleanText });
      }
    }

    // add the link itself
    // links usually don't need surrounding spaces inside the anchor tag, so we trim content slightly or keep as is
    const cleanLinkText = decodeHtmlEntities(linkText.replace(/<[^>]+>/g, ''));
    if (cleanLinkText) {
      nodes.push({
        type: "link",
        url: url,
        children: [{ type: "text", text: cleanLinkText }]
      });
    }

    lastIndex = index + fullMatch.length;
  }

  // add text after the last link
  if (lastIndex < html.length) {
    const textPart = html.substring(lastIndex);
    const cleanText = decodeHtmlEntities(textPart.replace(/<[^>]+>/g, ''));
    if (cleanText) {
      nodes.push({ type: "text", text: cleanText });
    }
  }

  // fallback if no links found return plain text
  if (nodes.length === 0) {
      const plain = decodeHtmlEntities(html.replace(/<[^>]+>/g, ''));
      if (plain) nodes.push({ type: "text", text: plain });
  }

  return nodes;
}

// get original data from the split in batches node
const sourceItems = $('split in batches').all(); 

// main loop
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const sourceItem = sourceItems[i] || {}; 

  const rawHtml = item.json.content || ""; 

  // sanitize category
  const rawCategory = item.json.category; 
  item.json.category = normalizeCategory(rawCategory);

  // calculate read time
  const plainText = rawHtml.replace(/<[^>]+>/g, ' ').trim();
  const readTime = calculateReadTime(plainText);

  // clean image url
  let rawImage = sourceItem.json && sourceItem.json.image;
  if (rawImage && typeof rawImage === 'string') {
      item.json.image = rawImage.split('/v1/fill/')[0];
  }

  // convert html to strapi blocks
  const blocks = [];

  const blockRegex = /<(h[1-6]|p|li|blockquote|a)[^>]*>([\s\S]*?)<\/\1>/gi;
  let match;

  while ((match = blockRegex.exec(rawHtml)) !== null) {
    const tag = match[1].toLowerCase();
    const innerHtml = match[2];
    const fullMatch = match[0];

    // For Logic Checks only: create a trimmed text version
    let cleanTextForCheck = innerHtml.replace(/<[^>]+>/g, '');
    cleanTextForCheck = decodeHtmlEntities(cleanTextForCheck).trim();

    // skip empty blocks unless it contains a link
    if (!cleanTextForCheck && !innerHtml.includes('<a')) continue;

    if (tag === 'a') {
      // HANDLE LOOSE LINKS
      const linkNodes = parseInlineContent(fullMatch);
      blocks.push({ type: "paragraph", children: linkNodes });

    } else if (tag === 'blockquote') {
      // HANDLE QUOTES
      const childrenNodes = parseInlineContent(innerHtml);
      blocks.push({ type: "paragraph", children: childrenNodes });

    } else if (tag.startsWith('h')) {
      const childrenNodes = parseInlineContent(innerHtml);
      blocks.push({
        type: "heading",
        level: parseInt(tag.charAt(1)) || 4,
        children: childrenNodes
      });

    } else if (tag === 'li') {
      const childrenNodes = parseInlineContent(innerHtml);
      childrenNodes.unshift({ type: "text", text: "• " });
      blocks.push({
        type: "paragraph",
        children: childrenNodes
      });

    } else {
      // paragraph logic
      const childrenNodes = parseInlineContent(innerHtml);

      // smart heading check (using the trimmed check text)
      if (cleanTextForCheck.length < 60 && (cleanTextForCheck.endsWith(':') || cleanTextForCheck.endsWith('..') || cleanTextForCheck.includes('?'))) {
         blocks.push({ type: "heading", level: 4, children: childrenNodes });
      } 
      // smart raw url check
      else if (isUrl(cleanTextForCheck) && childrenNodes.length === 1 && childrenNodes[0].type === 'text') {
        let url = cleanTextForCheck;
        if (!url.startsWith('http')) { url = 'http://' + url; }
        blocks.push({ type: "paragraph", children: [{ type: "link", url: url, children: [{ type: "text", text: cleanTextForCheck }] }] });
      } 
      else {
        blocks.push({ type: "paragraph", children: childrenNodes });
      }
    }
  }

  // fallback
  if (blocks.length === 0 && plainText.length > 0) {
    blocks.push({ type: "paragraph", children: parseInlineContent(rawHtml) });
  }

  item.json.strapi_blocks = blocks;
  item.json.read_time_calculated = readTime;
}

return items;
